async topUp({
    customer,
    balance,
    creditService,
}: {
    customer: ReadCustomerResponseData;
    balance?: number;
    creditService?: CreditService;
}): Promise<void> {
    const service = creditService || this.creditService;
    if (!service || !this.topUpAmount) {
        return;
    }
    let currentBalance = balance;
    if (currentBalance === undefined || currentBalance === null) {
        const { balance: foundBalance } = await service.findCreditBalance(
            { businessID: this.businessID, customerId: this.customerId },
            false,
        );
        currentBalance = parseFloat(foundBalance);
    }
    const topUpAmount = parseFloat(this.topUpAmount);
    const topUpThreshold = parseFloat(this.topUpThreshold ?? '0.2');
    const threshold = topUpThreshold * topUpAmount;
    if (currentBalance < threshold) {
        const gap = parseFloat((topUpAmount - currentBalance).toFixed(2));
        if (gap <= 0) {
            return;
        }
        const lineItems = new InvoiceLineItems();
        lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, gap));
        await this.invoicesService.create({
            businessID: this.businessID,
            customerId: this.customerId,
            customer,
            items: lineItems,
            storePaymentAsCredit: true,
            currency: Offering.getCurrency({ customer, offering: this }),
        });
    }
}

async processTopUpHourly({
    customer,
    creditService,
}: {
    customer: ReadCustomerResponseData;
    creditService?: CreditService;
}): Promise<void> {
    const service = creditService || this.creditService;
    const endDate = new Date();
    const startDate = new Date(endDate.getTime() - 60 * 60 * 1000);
    const lineItems = new InvoiceLineItems();
    await Offering.getLineItemsForUsage({
        startDate,
        endDate,
        customer,
        lineItems,
        negative: false,
        businessID: this.businessID,
        customerId: this.customerId,
        customerService: this.customerService,
        offeringInstance: this,
        dimensions: this.dimensions,
    });
    const usageTotal = parseFloat(lineItems.getTotal().toFixed(2));
    let currentBalance = 0;
    if (service) {
        const { balance } = await service.findCreditBalance(
            { businessID: this.businessID, customerId: this.customerId },
            false,
        );
        currentBalance = parseFloat(balance);
    }
    if (usageTotal > 0 && service) {
        await service.create({
            businessID: this.businessID,
            customerId: this.customerId,
            transactionAmount: (-usageTotal).toFixed(2),
            allowNegativeBalance: true,
            metadata: {
                offeringId: this.offeringId,
                reason: `Hourly usage for ${this.offeringName}`,
            },
            timestamp: new Date().toISOString(),
        });
        currentBalance = currentBalance - usageTotal;
    }
    await this.topUp({ customer, balance: currentBalance, creditService: service });
}

